def visit_BinOp(self, node: BinOp) -> Any:
    self.generic_visit(node)

    if isinstance(node.op, BitOr):
        # If either branch of the BinOp has been transformed to `None`, it means
        # that a type in the union was ignored, so the entire annotation should e
        # ignored
        if not hasattr(node, "left") or not hasattr(node, "right"):
            return None

        # Return Any if either side is Any
        if self._memo.name_matches(node.left, *anytype_names):
            return node.left
        elif self._memo.name_matches(node.right, *anytype_names):
            return node.right

        # Always transform PEP 604 union types (X | Y) into typing.Union[X, Y]
        # for compatibility with typeguard, regardless of Python version
        union_name = self.transformer._get_import("typing", "Union")
        return Subscript(
            value=union_name,
            slice=Tuple(elts=[node.left, node.right], ctx=Load()),
            ctx=Load(),
        )

    return node

from typeguard import typechecked
from typing import List, Dict, TypeVar, Generic, Optional, Union, ForwardRef

T = TypeVar('T')

class MyGeneric(Generic[T]):
    def __init__(self, value: T):
        self.value = value

# Forward reference
class MyClass:
    pass

@typechecked
def test_nested_union(x: int | (str | bytes)) -> None:
    print(f"test_nested_union: {x}, type: {type(x)}")

@typechecked
def test_complex_union(
    a: int | List[str],
    b: str | Dict[str, float],
    c: bytes | Optional[bool]
) -> None:
    print(f"test_complex_union: a={a}, type: {type(a)}")
    print(f"test_complex_union: b={b}, type: {type(b)}")
    print(f"test_complex_union: c={c}, type: {type(c)}")

# Use Union for forward references
@typechecked
def test_forward_ref(x: Union[int, ForwardRef('MyClass')]) -> None:
    print(f"test_forward_ref: {x}, type: {type(x)}")

@typechecked
def test_type_var(x: int | T) -> T:
    print(f"test_type_var: {x}, type: {type(x)}")
    if isinstance(x, int):
        return x  # This should fail type checking if T is not int
    return x

# Test with various inputs
print("Testing nested union:")
test_nested_union(123)
test_nested_union("hello")
test_nested_union(b"world")

print("\nTesting complex union:")
test_complex_union(123, "hello", b"world")
test_complex_union(["a", "b", "c"], {"key1": 1.0, "key2": 2.5}, True)

print("\nTesting forward reference:")
test_forward_ref(123)
test_forward_ref(MyClass())

print("\nTesting type variable:")
try:
    result1 = test_type_var[str](123)  # This should fail at runtime
    print(f"Result: {result1}, type: {type(result1)}")
except TypeError as e:
    print(f"Got expected TypeError: {e}")

result2 = test_type_var[str]("hello")
print(f"Result: {result2}, type: {type(result2)}")
